package com.bank.hop;

import java.util.logging.Logger;

public class MinHopPlanner {

    private static final Logger log = Logger.getLogger(MinHopPlanner.class.getName());

    public int minJumps(int[] jumps) {
        int count = 0, end = 0, farthest = 0;
        for (int i = 0; i < jumps.length - 1; i++) {   // never jump from last index
            farthest = Math.max(farthest, i + jumps[i]); // scout the window
            if (i == end) {                            // reached edge of current window
                count++;                               // one BFS layer / one hop
                end = farthest;                        // open next window
            }
        }
        final int result = count;
        log.info(() -> "Minimum jumps = " + result);
        return result;
    }
}
