package com.bank.hop;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class JumpGameIIDemo {

    private static final Logger log = Logger.getLogger(JumpGameIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Min Hop Planner (Jump Game II)");
        MinHopPlanner planner = new MinHopPlanner();
        log.info("{2,3,1,1,4} → " + planner.minJumps(new int[]{2, 3, 1, 1, 4})); // 2
        log.info("{2,3,0,1,4} → " + planner.minJumps(new int[]{2, 3, 0, 1, 4})); // 2
    }
}
